def calculer_durees(apps, schema_editor):
    """Durée en jours (bornes comprises) des activités qui ont leurs deux dates."""
    Activite = apps.get_model("projects", "Activite")
    a_mettre_a_jour = []
    for activite in Activite.objects.exclude(date_debut=None).exclude(date_fin=None):
        jours = (activite.date_fin - activite.date_debut).days + 1
        activite.nb_jours_planifies = jours if jours > 0 else None
        a_mettre_a_jour.append(activite)
    Activite.objects.bulk_update(a_mettre_a_jour, ["nb_jours_planifies"])


